"""Exact lattice bases from rational generating vectors."""

from __future__ import annotations

from fractions import Fraction
from math import lcm


def lattice_basis(vectors) -> list[list[Fraction]]:
    """A basis (rows, echelon form) of the lattice generated by `vectors`.

    Args:
        vectors: rational n-vectors spanning n dimensions

    Returns:
        n basis vectors as lists of `Fraction`
    """
    vectors = [[Fraction(x) for x in v] for v in vectors]
    n = len(vectors[0])
    denominator = lcm(*(x.denominator for v in vectors for x in v))
    rows = [[int(x * denominator) for x in v] for v in vectors]
    rows = [r for r in rows if any(r)]
    basis = []
    for col in range(n):
        while True:
            active = [r for r in rows if r[col] != 0]
            if len(active) <= 1:
                break
            pivot = min(active, key=lambda r: abs(r[col]))
            for r in active:
                if r is not pivot:
                    q = r[col] // pivot[col]
                    for j in range(n):
                        r[j] -= q * pivot[j]
        active = [r for r in rows if r[col] != 0]
        if not active:
            raise ValueError("Vectors do not span a full-rank lattice")
        basis.append(active[0])
        rows = [r for r in rows if r is not active[0]]
    return [[Fraction(x, denominator) for x in r] for r in basis]
